// A text's typing-out at 0x5BE11 ends its 256-byte copy at the count of letters shown, which a fast text's speed takes
// past the buffer (1071 on the Multiplayer page). On the console that zero lands in other memory; here past the stack's
// top, a crash. By then the whole text shows, so the copy's own last byte does the same.
void ClampTextEnd(X86Context& ctx, uint8_t*) {
    if (ctx.eax > 0xFF) ctx.eax = 0xFF;
}

// A model's parts, drawn from a list: 0x14AD30 (cdecl: filter, entity, first index, count, list of 12 byte entries, flag) batches
// parts of one key, and at the end of a batch reads the next entry's key without looking whether the list has ended. Past the end of
// 0x14B22B's list is the stack: Harry's crash, a stale entry with this key and no material, read at 0x14AE52 as null + 0x2C0.
// A key no part has stands past the end during the call, for a list on the stack only: past a global list (0x14AF80's) may be
// anything. 0x14B22B's list holds 8 and its start index (the third argument, a word the call reads first) follows it: a full
// list's key slot is that index, which the mark set to 0xFFFF, and the call began 65535 entries on (a USA player's crash, 1.0.0).
// That slot is left alone; a key there is the index's own bytes, no part's.
X86_EXTERN_FUNC(__imp__sub_0014AC40);
X86_FUNC(sub_0014AC40) {
    const uint32_t start = kernel::R32(ctx.esp + 0xC), list = kernel::R32(ctx.esp + 0x14);
    const uint32_t past_key = list + kernel::R32(ctx.esp + 0x10) * 12 + 8;
    const bool on_stack = list > ctx.esp && list - ctx.esp < 0x1000;
    const bool apart = past_key + 4 <= start || past_key >= start + 4;
    if (!on_stack || !apart) {
        if (on_stack) LOG_FIRST(4, "auf: a full list of model parts, its start index after it left alone");
        return __imp__sub_0014AC40(ctx, base);
    }
    const uint32_t kept = kernel::R32(past_key);
    kernel::W32(past_key, 0xFFFFFFFF);
    __imp__sub_0014AC40(ctx, base);
    kernel::W32(past_key, kept);
}

// Hit flash (auf::hit_flash): the HUD's draw 0x53840 (ebx its player's view) fills the screen white at the alpha [ebx+0x30], which
// damage raises and time lowers, and skips the fill at 0 (0x539A9 to 0x53A5B). With the setting off the alpha is 0 there, so
// the fill is left out. (The player's setflashcolor at 0xBB4A6 is not the flash on screen: its handler never runs on a hit.)
void NoHitFlash(X86Context& ctx, uint8_t*) {
    if (auf::hit_flash || kernel::R32(ctx.ebx + 0x30) == 0) return;
    LOG_FIRST(1, "auf: the hit flash left out (hit_flash off)");
    kernel::W32(ctx.ebx + 0x30, 0);
}


// Test switches (a save made with them keeps what they did). The select screen opens mission m+1 when the dword
// 0x207630 + 4m is 1 (0x20762C, mission 0, always is; a profile's load rebuilds them, so they are written each frame);
// Start Mission (0x4AA40, events 2 and 0x16) loads the map of the mission 0x2A9F98 holds at the press.
// AUF_UNLOCK=1: every mission open. AUF_MISSION=n (0 to 11): Start Mission starts mission n.
// every mission open also while tuning sights (the guns come with each mission's models) and in LAN play: written each
// frame and before the select page's own code reads the flags (0x4718D its presses, 0x3C51D and 0x42480 its picture)
// In LAN play (not co-op) also every reward of the 12 missions (the flags 0x2A9B8C + 4m: what mission m's clearing opens in the
// multiplayer, text ids 930 to 941: the Rocket Manor map, the Golden Gun mode, the Stealth Bond, Guard, Alpine Guard,
// Cyclops Oil Guard, Poseidon Guard and Carrier Guard models, the Viper and Calypso, Full Arsenal, Gravity Boots; and
// 0x2A9BBC + 4m: the gold medal bonuses, ids 1037 to 1048), so each copy of a game has all of them to choose from.
static void UnlockMissions() {
    static const bool unlock = std::getenv("AUF_UNLOCK") != nullptr;
    // LAN play but not story co-op (co-op keeps the profile as it is, and saves): everything open, nothing saved
    const bool lan = netplay::Active() && !auf::CoopOn();
    kernel::BlockSaveWrites(lan);
    if (unlock || auf::sight_tuner || lan)
        for (uint32_t m = 0; m < 11; m++) kernel::G<uint32_t>(A(0x207630) + 4 * m) = 1;
    if (unlock || lan)
        for (uint32_t m = 0; m < 12; m++) {
            kernel::G<uint32_t>(A(0x2A9B8C) + 4 * m) = 1;
            kernel::G<uint32_t>(A(0x2A9BBC) + 4 * m) = 1;
        }
}
